-- First-party, versioned provider data initialization. Retain any already
-- managed inventory, including custom definitions, tombstones and overrides.
-- No role selection or credential is created/changed here. Later startup is
-- read-only with respect to provider definitions; the marker survives removals.
CREATE TABLE IF NOT EXISTS brassclaw_llm_provider_initializations (
    tenant_id TEXT PRIMARY KEY,
    data_revision BIGINT NOT NULL CHECK(data_revision > 0),
    seed_checksum TEXT NOT NULL CHECK(seed_checksum ~ '^[0-9a-f]{64}$'),
    mode TEXT NOT NULL CHECK(mode IN ('fresh','retained')),
    initialized_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

