CREATE OR REPLACE FUNCTION brassclaw_provider_initialization_immutable()
RETURNS trigger LANGUAGE plpgsql AS $guard$
BEGIN
    RAISE EXCEPTION 'provider initialization provenance is immutable' USING ERRCODE='42501';
END
