ON brassclaw_llm_provider_initializations FOR EACH ROW
EXECUTE FUNCTION brassclaw_provider_initialization_immutable();
DROP TRIGGER IF EXISTS provider_initialization_no_truncate ON brassclaw_llm_provider_initializations;
